import type { PROFILE_QUERY_RESULT } from "@/shared/lib/sanity/types";

/** Result of `PROFILE_QUERY` (generated by Sanity TypeGen), minus the `null` for "no document". */
export type ProfileData = NonNullable<PROFILE_QUERY_RESULT>;

export type ProfileMetric = NonNullable<ProfileData["metrics"]>[number];
export type ProfileTech = NonNullable<ProfileData["techStack"]>[number];
